    leaks: ['guess-array-room', '数组里的房间不应展开'],
  },
  { label: '顶层为字符串', body: '"guess-string-room"', leaks: ['guess-string-room'] },
  {
    label: '对象缺少 rooms，但其他字段像房间（不能猜）',
    body: '{"room":{"id":"guess-room"},"data":[{"id":"guess-data"}]}',
